sys_variable_value.value:
// ATF injects assertEqual, steps, outputs, stepResult and an enclosing try block - bare body.
// steps(SYS_ID) is ATF's injected accessor for an earlier step's outputs. GEM {{ step[...] }}
// templates are NOT substituted in a script body, so the sys_id must be passed literally.
var invoiceId = steps("8639018182c540ea9f6f4c326fb8694c").record_id;
if (!invoiceId || ('' + invoiceId).length !== 32) {
    throw new Error('unresolved step reference for invoiceId: ' + invoiceId);
}
function num(v) { return parseFloat(v) || 0; }

var inv = new GlideRecord('x_2298436_snackf_0_invoice');
if (!inv.get(invoiceId)) throw new Error('invoice not found');

// Re-sum the surviving payments independently and compare to the stored rollup.
var summed = 0, rows = 0;
var p = new GlideRecord('x_2298436_snackf_0_payment');
p.addQuery('invoice', invoiceId);
p.query();
while (p.next()) { summed += num(p.getValue('payment_amount')); rows++; }
summed = Math.round(summed * 100) / 100;

assertEqual({ name: 'one payment remains after the delete', shouldbe: 1, value: rows });
assertEqual({ name: 'amount_paid equals an independent re-sum of payments', shouldbe: summed, value: num(inv.getValue('amount_paid')) });
assertEqual({
    name: 'balance_due = total - amount_paid',
    shouldbe: Math.round((num(inv.getValue('total_invoice_amount')) - summed) * 100) / 100,
    value: num(inv.getValue('balance_due')),
});

// Back in outstanding receivables now that a balance remains.
var out = new GlideRecord('x_2298436_snackf_0_invoice');
out.addQuery('sys_id', invoiceId);
out.addQuery('balance_due', '>', 0);
out.query();
assertEqual({ name: 'invoice re-enters outstanding receivables', shouldbe: true, value: out.hasNext() });

stepResult.setOutputMessage(
    'payments=' + rows + ' summed=' + summed + ' amount_paid=' + inv.getValue('amount_paid') +
    ' balance_due=' + inv.getValue('balance_due') + ' status=' + inv.getValue('invoice_status')
);
